mcp:tool-listener.mcp:parameters-schema:
{
  "type": "object",
  "properties": {
    "name": { "type": "string", "description": "Person or company name" },
    "birthDate": { "type": "string", "description": "YYYY-MM-DD, for a person, if known" }
  },
  "required": ["name"]
}

ee:message.ee:set-payload:
%dw 2.0
output application/json indent=false
fun key(s) = upper(((s default '') replace /[（(][^）)]*[）)]/ with '') replace /株式会社|\s|　/ with '')
var k = key(vars.req.name)
var bd = vars.req.birthDate default ''
---
{
  screened: vars.req.name,
  hits: (payload filter (k != '' and ($.name_key == k or (k contains $.name_key) or ($.name_key contains k)))) map {
    list: $.list_name, entityType: $.entity_type, listedName: $.name, country: $.country,
    reason: $.reason, listedOn: $.listed_on,
    match: if ($.name_key == k) "exact" else "partial",
    listedBirthDate: $.birth_date,
    birthDateMatch: if ($.birth_date == null or bd == '') "unknown" else ($.birth_date == bd)
  }
}

%dw 2.0
output application/json indent=false
fun key(s) = upper(((s default '') replace /[（(][^）)]*[）)]/ with '') replace /株式会社|\s|　/ with '')
var k = key(vars.req.name)
---
{
  searched: vars.req.name,
  articles: (payload filter (k != '' and ($.names default '') != '' and ((k contains $.names) or ($.names contains k)))) map {
    publishedOn: $.published_on, source: $.source, title: $.title, body: $.body
  }
}

mcp:tool-listener.mcp:parameters-schema:
{
  "type": "object",
  "properties": {
    "parties": {
      "type": "array",
      "items": { "type": "string" },
      "description": "Names to check. Write a person as \"name (YYYY-MM-DD)\" when the birth date is known, e.g. \"黒田 隆 (1974-11-02)\"; a company as its name."
    }
  },
  "required": ["parties"]
}

ee:message.ee:set-payload:
%dw 2.0
output application/json indent=false
fun key(s) = upper(((s default '') replace /[（(][^）)]*[）)]/ with '') replace /株式会社|\s|　/ with '')
var news = payload
---
{
  parties: (vars.req.parties default []) map ((p) -> do {
    var k = key(p)
    var bd = (p match /.*?(\d{4}-\d{2}-\d{2}).*/) [1] default ''
    ---
    {
      name: p,
      watchlistHits: (vars.watchlist filter (k != '' and ($.name_key == k or (k contains $.name_key) or ($.name_key contains k)))) map {
        list: $.list_name, entityType: $.entity_type, listedName: $.name, country: $.country,
        reason: $.reason, listedOn: $.listed_on,
        match: if ($.name_key == k) "exact" else "partial",
        listedBirthDate: $.birth_date,
        birthDateMatch: if ($.birth_date == null or bd == '') "unknown" else ($.birth_date == bd)
      },
      news: (news filter (k != '' and ($.names default '') != '' and ((k contains $.names) or ($.names contains k)))) map {
        publishedOn: $.published_on, source: $.source, title: $.title, body: $.body
      }
    }
  })
}
